content.content:
1	/**
2	 * asaas-tokenize-card — Tokeniza cartão de crédito da empresa no Asaas.
3	 *
4	 * Fluxo postpago (Slice 2 / ADR-20260622-pagamento-postpago):
5	 *  1. Garante que a empresa tem um asaas_customer_id (cria se não tiver).
6	 *  2. Envia dados do cartão para POST /v3/creditCard/tokenizeCreditCard (PAN só nesta
7	 *     chamada server→Asaas; NUNCA gravado no DB — Article 10 / PCI).
8	 *  3. Grava o token opaco + metadados em payment_methods (UNIQUE por company+token).
9	 *  4. Marca o novo método como default; desmarca o anterior.
10	 *
11	 * Deploy normal (com verify-jwt) — chamada autenticada pela empresa.
12	 * Article 10: service_role apenas no Deno (Supabase Admin); sem chave no frontend.
13	 */
14	
15	import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
16	import { createClient } from 'jsr:@supabase/supabase-js@2';
17	import { getCorsHeaders, ASAAS_API_URL, getAsaasHeaders } from '../_shared/asaas.ts';
18	import { isRateLimited } from '../_shared/rate-limit.ts';
19	
20	// ---------------------------------------------------------------------------
21	// Tipos de input
22	// ---------------------------------------------------------------------------
23	
24	interface HolderInfo {
25	  name: string;
26	  email: string;
27	  cpfCnpj: string;
28	  postalCode: string;
29	  addressNumber: string;
30	  phone: string;
31	}
32	
33	interface TokenizeCardInput {
34	  holderName: string;
35	  number: string;
36	  expiryMonth: string;
37	  expiryYear: string;
38	  ccv: string;
39	  holderInfo: HolderInfo;
40	}
41	
42	// ---------------------------------------------------------------------------
43	// Serve
44	// ---------------------------------------------------------------------------
45	
46	serve(async (req) => {
47	  const corsHeaders = getCorsHeaders(req);
48	
49	  if (req.method === 'OPTIONS') {
50	    return new Response('ok', { headers: corsHeaders });
51	  }
52	
53	  try {
54	    // --- Admin client (service_role só no Deno) ---
55	    const supabaseAdmin = createClient(
56	      Deno.env.get('SUPABASE_URL') ?? '',
57	      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
58	    );
59	
60	    // --- Auth ---
61	    const authHeader = req.headers.get('Authorization');
62	    if (!authHeader) throw new Error('Missing Authorization header');
63	    const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7) : authHeader;
64	    const { data: { user }, error: userError } = await supabaseAdmin.auth.getUser(token);
65	    if (userError || !user) throw new Error('Invalid Token');
66	
67	    // --- Rate limit: 3 tokenizações por minuto por empresa ---
68	    if (isRateLimited(user.id, 'tokenize-card', 3, 60_000)) {
69	      return new Response(
70	        JSON.stringify({ error: 'Muitas tentativas. Aguarde 1 minuto.' }),
71	        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 429 }
72	      );
73	    }
74	
75	    // --- Parse do body ---
76	    const body: TokenizeCardInput = await req.json();
77	    const { holderName, number, expiryMonth, expiryYear, ccv, holderInfo } = body;
78	
79	    if (!holderName || !number || !expiryMonth || !expiryYear || !ccv) {
80	      throw new Error('Dados do cartão incompletos.');
81	    }
82	    if (!holderInfo?.cpfCnpj || !holderInfo?.name) {
83	      throw new Error('holderInfo obrigatório: name e cpfCnpj.');
84	    }
85	
86	    // --- Resolver company_id (owner_id = auth.uid()) ---
87	    const { data: company, error: companyErr } = await supabaseAdmin
88	      .from('companies')
89	      .select('id')
90	      .eq('owner_id', user.id)
91	      .maybeSingle();
92	
93	    if (companyErr || !company) {
94	      throw new Error('Perfil de empresa não encontrado.');
95	    }
96	    const companyId: string = company.id;
97	
98	    // --- Garantir carteira e asaas_customer_id ---
99	    const { data: wallet, error: walletErr } = await supabaseAdmin
100	      .from('wallets')
101	      .select('id, asaas_customer_id')
102	      .eq('user_id', user.id)
103	      .maybeSingle();
104	
105	    if (walletErr || !wallet) {
106	      throw new Error('Carteira não encontrada. Conclua o onboarding primeiro.');
107	    }
108	
109	    let customerId: string = wallet.asaas_customer_id ?? '';
110	
111	    // Criar customer no Asaas se não existir (mesmo padrão do asaas-deposit)
112	    if (!customerId) {
113	      const cleanDoc = holderInfo.cpfCnpj.replace(/\D/g, '');
114	      const customerRes = await fetch(`${ASAAS_API_URL}/customers`, {
115	        method: 'POST',
116	        headers: getAsaasHeaders(),
117	        body: JSON.stringify({
118	          name: holderInfo.name,
119	          cpfCnpj: cleanDoc,
120	          email: holderInfo.email,
121	          phone: holderInfo.phone,
122	        }),
123	      });
124	      const customerData = await customerRes.json();
125	      if (!customerRes.ok) {
126	        throw new Error(
127	          customerData.errors?.[0]?.description || 'Erro ao criar conta de pagamento.'
128	        );
129	      }
130	      customerId = customerData.id;
131	      await supabaseAdmin
132	        .from('wallets')
133	        .update({ asaas_customer_id: customerId })
134	        .eq('user_id', user.id)
135	        .throwOnError();
136	    }
137	
138	    // --- remoteIp para conformidade Asaas (exigido pelo endpoint de tokenização) ---
139	    const remoteIp =
140	      req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ||
141	      req.headers.get('x-real-ip') ||
142	      '0.0.0.0';
143	
144	    // --- Tokenizar cartão no Asaas (PAN só nesta chamada — nunca gravado) ---
145	    const tokenizeRes = await fetch(`${ASAAS_API_URL}/creditCard/tokenizeCreditCard`, {
146	      method: 'POST',
147	      headers: getAsaasHeaders(),
148	      body: JSON.stringify({
149	        customer: customerId,
150	        creditCard: {
151	          holderName,
152	          number,
153	          expiryMonth,
154	          expiryYear,
155	          ccv,
156	        },
157	        creditCardHolderInfo: {
158	          name: holderInfo.name,
159	          email: holderInfo.email,
160	          cpfCnpj: holderInfo.cpfCnpj.replace(/\D/g, ''),
161	          postalCode: holderInfo.postalCode.replace(/\D/g, ''),
162	          addressNumber: holderInfo.addressNumber,
163	          phone: holderInfo.phone.replace(/\D/g, ''),
164	        },
165	        remoteIp,
166	      }),
167	    });
168	
169	    const tokenizeData = await tokenizeRes.json();
170	    if (!tokenizeRes.ok) {
171	      throw new Error(
172	        tokenizeData.errors?.[0]?.description ||
173	        tokenizeData.error ||
174	        'Cartão recusado ou dados inválidos.'
175	      );
176	    }
177	
178	    const asaasCreditCardToken: string = tokenizeData.creditCardToken;
179	    const brand: string = tokenizeData.creditCardBrand ?? '';
180	    // last4: Asaas retorna creditCardNumber mascarado (ex: "•••• 1234") — extraímos os 4 últimos dígitos
181	    const last4Raw: string = tokenizeData.creditCardNumber ?? '';
182	    const last4 = last4Raw.replace(/\D/g, '').slice(-4) || null;
183	
184	    if (!asaasCreditCardToken) {
185	      throw new Error('Asaas não retornou o token do cartão.');
186	    }
187	
188	    // --- Desmarcar default anterior (se houver) ---
189	    await supabaseAdmin
190	      .from('payment_methods')
191	      .update({ is_default: false })
192	      .eq('company_id', companyId)
193	      .eq('is_default', true);
194	
195	    // --- Gravar método de pagamento (idempotente: UNIQUE company_id + token) ---
196	    const { data: pm, error: pmErr } = await supabaseAdmin
197	      .from('payment_methods')
198	      .upsert(
199	        {
200	          company_id: companyId,
201	          asaas_credit_card_token: asaasCreditCardToken,
202	          brand: brand || null,
203	          last4,
204	          holder_name: holderName,
205	          is_default: true,
206	        },
207	        { onConflict: 'company_id,asaas_credit_card_token', ignoreDuplicates: false }
208	      )
209	      .select('id, brand, last4')
210	      .single();
211	
212	    if (pmErr || !pm) {
213	      throw new Error('Erro ao salvar método de pagamento.');
214	    }
215	
216	    return new Response(
217	      JSON.stringify({
218	        success: true,
219	        paymentMethodId: pm.id,
220	        brand: pm.brand,
221	        last4: pm.last4,
222	      }),
223	      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
224	    );
225	  } catch (error: unknown) {
226	    const msg = error instanceof Error ? error.message : 'Erro interno.';
227	    console.error('asaas-tokenize-card error:', msg);
228	    return new Response(
229	      JSON.stringify({ error: msg }),
230	      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 400 }
231	    );
232	  }
233	});
234

1	/**
2	 * asaas-authorize-payment — Pré-autoriza (hold) o cartão da empresa no aceite do convite.
3	 *
4	 * Fluxo postpago (Slice 2 / ADR-20260622-pagamento-postpago):
5	 *  Chamado pelo ShiftInviteService.respondToInvite('accepted') após o status da application
6	 *  mudar para 'hired'. Cria o hold (authorizeOnly:true) no Asaas e grava o escrow 'authorized'
7	 *  no DB via RPC atômica authorize_escrow_postpago.
8	 *
9	 * Modo controlado por env ASAAS_POSTPAGO_MODE:
10	 *  - 'authorize' (default)    : fluxo normal pré-auth → capture.
11	 *  - 'charge_on_demand'       : pula a pré-auth; a captura acontece na conclusão. Neste caso
12	 *                               a função retorna success sem criar hold nem chamar a RPC.
13	 *
14	 * Idempotência:
15	 *  - idx_escrow_unique_asaas_payment (UNIQUE asaas_payment_id): reprocesso não cria 2º escrow.
16	 *  - 23505 do índice idx_escrow_one_authorized_per_job → tratar como já-autorizado.
17	 *
18	 * Deploy normal (com verify-jwt) — caller é o WORKER autenticado.
19	 * Article 10: service_role apenas no Deno.
20	 */
21	
22	import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
23	import { createClient } from 'jsr:@supabase/supabase-js@2';
24	import { getCorsHeaders, ASAAS_API_URL, getAsaasHeaders } from '../_shared/asaas.ts';
25	import { isRateLimited } from '../_shared/rate-limit.ts';
26	
27	serve(async (req) => {
28	  const corsHeaders = getCorsHeaders(req);
29	
30	  if (req.method === 'OPTIONS') {
31	    return new Response('ok', { headers: corsHeaders });
32	  }
33	
34	  try {
35	    const supabaseAdmin = createClient(
36	      Deno.env.get('SUPABASE_URL') ?? '',
37	      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
38	    );
39	
40	    // --- Auth (caller = worker) ---
41	    const authHeader = req.headers.get('Authorization');
42	    if (!authHeader) throw new Error('Missing Authorization header');
43	    const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7) : authHeader;
44	    const { data: { user }, error: userError } = await supabaseAdmin.auth.getUser(token);
45	    if (userError || !user) throw new Error('Invalid Token');
46	
47	    if (isRateLimited(user.id, 'authorize-payment', 5, 60_000)) {
48	      return new Response(
49	        JSON.stringify({ error: 'Muitas tentativas. Aguarde 1 minuto.' }),
50	        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 429 }
51	      );
52	    }
53	
54	    const { jobId, applicationId } = await req.json();
55	    if (!jobId || !applicationId) throw new Error('jobId e applicationId são obrigatórios.');
56	
57	    // --- Verificar que o caller é o worker desta application ---
58	    const { data: app, error: appErr } = await supabaseAdmin
59	      .from('applications')
60	      .select('id, worker_id, job_id, status, invited_by_company_at')
61	      .eq('id', applicationId)
62	      .maybeSingle();
63	
64	    if (appErr || !app) throw new Error('Candidatura não encontrada.');
65	    if (app.worker_id !== user.id) throw new Error('Não autorizado: esta candidatura não é sua.');
66	    if (app.job_id !== jobId) throw new Error('jobId não corresponde à candidatura.');
67	    if (!app.invited_by_company_at) {
68	      throw new Error('Esta candidatura não é um convite push (invited_by_company_at ausente).');
69	    }
70	    if (app.status !== 'hired') {
71	      throw new Error(
72	        `Status da candidatura deve ser 'hired' para autorizar pagamento, mas é '${app.status}'.`
73	      );
74	    }
75	
76	    // --- Verificar se já existe escrow postpago para este job (idempotência) ---
77	    const { data: existingEscrow } = await supabaseAdmin
78	      .from('escrow_transactions')
79	      .select('id, asaas_payment_id, status')
80	      .eq('job_id', jobId)
81	      .eq('kind', 'postpaid')
82	      .eq('status', 'authorized')
83	      .maybeSingle();
84	
85	    if (existingEscrow) {
86	      // Já autorizado — idempotência: retorna o existente sem criar 2º hold
87	      return new Response(
88	        JSON.stringify({
89	          success: true,
90	          escrowId: existingEscrow.id,
91	          asaasPaymentId: existingEscrow.asaas_payment_id,
92	          status: 'authorized',
93	          idempotent: true,
94	        }),
95	        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
96	      );
97	    }
98	
99	    // --- Modo: 'authorize' | 'charge_on_demand' ---
100	    const mode = Deno.env.get('ASAAS_POSTPAGO_MODE') ?? 'authorize';
101	
102	    if (mode === 'charge_on_demand') {
103	      // Pula a pré-auth; captura será feita na conclusão. Retorna success sem escrow.
104	      console.log(`[authorize-payment] charge_on_demand mode: skip hold for job=${jobId}`);
105	      return new Response(
106	        JSON.stringify({ success: true, status: 'charge_on_demand', mode }),
107	        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
108	      );
109	    }
110	
111	    // --- Buscar dados do job (valor + company_id) ---
112	    const { data: job, error: jobErr } = await supabaseAdmin
113	      .from('jobs')
114	      .select('company_id, budget, title')
115	      .eq('id', jobId)
116	      .maybeSingle();
117	
118	    if (jobErr || !job) throw new Error('Vaga não encontrada.');
119	    const amount: number = job.budget;
120	    if (!amount || amount <= 0) throw new Error('Budget da vaga inválido para pré-autorização.');
121	
122	    const companyUserId: string = job.company_id;
123	
124	    // --- Buscar método de pagamento default da empresa ---
125	    const { data: pm, error: pmErr } = await supabaseAdmin
126	      .from('payment_methods')
127	      .select('asaas_credit_card_token, brand, last4')
128	      .eq('company_id', companyUserId)
129	      .eq('is_default', true)
130	      .maybeSingle();
131	
132	    if (pmErr || !pm) {
133	      throw new Error(
134	        'A empresa não possui método de pagamento cadastrado. ' +
135	        'Solicite ao operador que cadastre um cartão antes de aceitar convites.'
136	      );
137	    }
138	
139	    // --- Buscar asaas_customer_id da empresa ---
140	    const { data: companyWallet, error: cwErr } = await supabaseAdmin
141	      .from('wallets')
142	      .select('asaas_customer_id')
143	      .eq('user_id', companyUserId)
144	      .maybeSingle();
145	
146	    if (cwErr || !companyWallet?.asaas_customer_id) {
147	      throw new Error('Conta de pagamento da empresa não encontrada no Asaas.');
148	    }
149	
150	    // --- remoteIp (exigido pelo Asaas para cobrança com cartão) ---
151	    const remoteIp =
152	      req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ||
153	      req.headers.get('x-real-ip') ||
154	      '0.0.0.0';
155	
156	    // dueDate = hoje + 1 dia (mínimo exigido pelo Asaas)
157	    const dueDate = new Date();
158	    dueDate.setDate(dueDate.getDate() + 1);
159	    const dueDateStr = dueDate.toISOString().split('T')[0];
160	
161	    // --- POST /v3/payments com authorizeOnly:true ---
162	    const paymentRes = await fetch(`${ASAAS_API_URL}/payments`, {
163	      method: 'POST',
164	      headers: getAsaasHeaders(),
165	      body: JSON.stringify({
166	        customer: companyWallet.asaas_customer_id,
167	        billingType: 'CREDIT_CARD',
168	        value: amount,
169	        dueDate: dueDateStr,
170	        description: `Turno reservado: ${job.title}`,
171	        externalReference: jobId,
172	        authorizeOnly: true,
173	        creditCardToken: pm.asaas_credit_card_token,
174	        remoteIp,
175	      }),
176	    });
177	
178	    const paymentData = await paymentRes.json();
179	
180	    // --- Tratar falha: pré-auth não habilitada → fallback charge_on_demand ---
181	    if (!paymentRes.ok) {
182	      const errMsg: string =
183	        paymentData.errors?.[0]?.description || paymentData.error || '';
184	      const isPreAuthDisabled =
185	        errMsg.toLowerCase().includes('autoriza') ||
186	        errMsg.toLowerCase().includes('authorize') ||
187	        paymentRes.status === 422;
188	
189	      if (isPreAuthDisabled) {
190	        console.warn(
191	          `[authorize-payment] Pré-auth não disponível (fallback charge_on_demand): ${errMsg}`
192	        );
193	        return new Response(
194	          JSON.stringify({ success: true, status: 'charge_on_demand', fallback: true, reason: errMsg }),
195	          { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
196	        );
197	      }
198	      throw new Error(errMsg || 'Erro ao criar pré-autorização no Asaas.');
199	    }
200	
201	    const asaasPaymentId: string = paymentData.id;
202	    if (!asaasPaymentId) throw new Error('Asaas não retornou o id da cobrança.');
203	
204	    // Status esperado: AUTHORIZED. Se não, logar mas prosseguir (Asaas pode retornar PENDING transitório)
205	    if (paymentData.status && paymentData.status !== 'AUTHORIZED') {
206	      console.warn(
207	        `[authorize-payment] Status Asaas inesperado: ${paymentData.status} para payment=${asaasPaymentId}`
208	      );
209	    }
210	
211	    // --- Gravar escrow 'authorized'/'postpaid' no DB (RPC atômica) ---
212	    const { data: escrowId, error: rpcErr } = await supabaseAdmin.rpc(
213	      'authorize_escrow_postpago',
214	      {
215	        p_job_id: jobId,
216	        p_application_id: applicationId,
217	        p_amount: amount,
218	        p_asaas_payment_id: asaasPaymentId,
219	        p_company_user_id: companyUserId,
220	      }
221	    );
222	
223	    if (rpcErr) {
224	      // 23505 = único violado (hold duplicado) — tratar como idempotente
225	      if (rpcErr.code === '23505') {
226	        console.warn(`[authorize-payment] Escrow duplicado (23505), tratando como idempotente.`);
227	        return new Response(
228	          JSON.stringify({ success: true, asaasPaymentId, status: 'authorized', idempotent: true }),
229	          { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
230	        );
231	      }
232	      // RPC falhou após criar o hold no Asaas — logar para reconciliação manual
233	      console.error(
234	        `[authorize-payment] RPC authorize_escrow_postpago falhou após hold criado. ` +
235	        `asaas_payment_id=${asaasPaymentId} job=${jobId}. Erro: ${rpcErr.message}`
236	      );
237	      throw new Error('Falha ao registrar escrow. O hold foi criado no Asaas — contacte o suporte.');
238	    }
239	
240	    return new Response(
241	      JSON.stringify({
242	        success: true,
243	        escrowId,
244	        asaasPaymentId,
245	        status: 'authorized',
246	      }),
247	      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
248	    );
249	  } catch (error: unknown) {
250	    const msg = error instanceof Error ? error.message : 'Erro interno.';
251	    console.error('asaas-authorize-payment error:', msg);
252	    return new Response(
253	      JSON.stringify({ error: msg }),
254	      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 400 }
255	    );
256	  }
257	});
258

1	/**
2	 * asaas-capture-payment — Captura o hold no Asaas e credita o worker na conclusão do turno.
3	 *
4	 * Fluxo postpago (Slice 2 / ADR-20260622-pagamento-postpago):
5	 *  Chamado pela empresa na conclusão do turno (espelha asaas-checkout para kind='postpaid').
6	 *  Também pode ser disparado por auto-processamento (cron — R9) após janela de carência.
7	 *
8	 *  Dois caminhos:
9	 *  A) Tem hold ativo (status='authorized'/'postpaid'):
10	 *     → captureAuthorizedPayment no Asaas → capture_escrow_postpago (credita worker).
11	 *  B) Sem hold (charge_on_demand / hold expirado):
12	 *     → charge direta com o token default da empresa → authorize_escrow_postpago + capture_escrow_postpago.
13	 *     (fallback — sem ADR adicional, mesmo gateway Asaas, Article 6 intacto.)
14	 *
15	 * Idempotência:
16	 *  - capture_escrow_postpago usa WHERE status='authorized' → double-capture não duplica crédito.
17	 *  - UNIQUE (wallet_id, reference_id) em wallet_transactions → idempotência do crédito.
18	 *
19	 * Deploy normal (com verify-jwt) — caller é a EMPRESA.
20	 * Article 10: service_role apenas no Deno.
21	 */
22	
23	import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
24	import { createClient } from 'jsr:@supabase/supabase-js@2';
25	import { getCorsHeaders, ASAAS_API_URL, getAsaasHeaders } from '../_shared/asaas.ts';
26	import { isRateLimited } from '../_shared/rate-limit.ts';
27	
28	serve(async (req) => {
29	  const corsHeaders = getCorsHeaders(req);
30	
31	  if (req.method === 'OPTIONS') {
32	    return new Response('ok', { headers: corsHeaders });
33	  }
34	
35	  try {
36	    const supabaseAdmin = createClient(
37	      Deno.env.get('SUPABASE_URL') ?? '',
38	      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
39	    );
40	
41	    // --- Auth (caller = empresa) ---
42	    const authHeader = req.headers.get('Authorization');
43	    if (!authHeader) throw new Error('Missing Authorization header');
44	    const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7) : authHeader;
45	    const { data: { user }, error: userError } = await supabaseAdmin.auth.getUser(token);
46	    if (userError || !user) throw new Error('Invalid Token');
47	
48	    if (isRateLimited(user.id, 'capture-payment', 5, 60_000)) {
49	      return new Response(
50	        JSON.stringify({ error: 'Muitas tentativas. Aguarde 1 minuto.' }),
51	        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 429 }
52	      );
53	    }
54	
55	    const { jobId, workerId } = await req.json();
56	    if (!jobId || !workerId) throw new Error('jobId e workerId são obrigatórios.');
57	
58	    // --- Verificar que o caller é dono do job ---
59	    const { data: job, error: jobErr } = await supabaseAdmin
60	      .from('jobs')
61	      .select('company_id, budget, title')
62	      .eq('id', jobId)
63	      .maybeSingle();
64	
65	    if (jobErr || !job) throw new Error('Vaga não encontrada.');
66	    if (job.company_id !== user.id) throw new Error('Não autorizado: você não é o dono desta vaga.');
67	
68	    // --- Verificar application concluída ou checkout confirmado ---
69	    const { data: app, error: appErr } = await supabaseAdmin
70	      .from('applications')
71	      .select('worker_id, status, company_checkout_confirmed_at')
72	      .eq('job_id', jobId)
73	      .eq('worker_id', workerId)
74	      .in('status', ['in_progress', 'completed'])
75	      .maybeSingle();
76	
77	    if (appErr || !app) {
78	      throw new Error('Candidatura não encontrada ou trabalho ainda não foi iniciado.');
79	    }
80	    if (app.status !== 'completed' && !app.company_checkout_confirmed_at) {
81	      throw new Error('O trabalho precisa estar concluído antes de liberar o pagamento.');
82	    }
83	
84	    // --- Get-or-create carteira do worker ---
85	    let workerWalletId: string;
86	    const { data: workerWallet } = await supabaseAdmin
87	      .from('wallets')
88	      .select('id')
89	      .eq('user_id', workerId)
90	      .maybeSingle();
91	
92	    if (workerWallet) {
93	      workerWalletId = workerWallet.id;
94	    } else {
95	      const { data: newWallet, error: createErr } = await supabaseAdmin
96	        .from('wallets')
97	        .insert({ user_id: workerId, balance: 0, user_type: 'worker' })
98	        .select('id')
99	        .single();
100	      if (createErr || !newWallet) throw new Error('Falha ao criar carteira do worker.');
101	      workerWalletId = newWallet.id;
102	    }
103	
104	    // --- Buscar escrow postpago 'authorized' ---
105	    const { data: escrow } = await supabaseAdmin
106	      .from('escrow_transactions')
107	      .select('id, asaas_payment_id, amount, status, captured_at')
108	      .eq('job_id', jobId)
109	      .eq('kind', 'postpaid')
110	      .maybeSingle();
111	
112	    // --- Caminho A: tem hold ativo → capturar ---
113	    if (escrow && escrow.status === 'authorized' && escrow.asaas_payment_id) {
114	      const asaasPaymentId: string = escrow.asaas_payment_id;
115	
116	      // captureAuthorizedPayment no Asaas
117	      const captureRes = await fetch(
118	        `${ASAAS_API_URL}/payments/${asaasPaymentId}/captureAuthorizedPayment`,
119	        {
120	          method: 'POST',
121	          headers: getAsaasHeaders(),
122	          body: JSON.stringify({}),
123	        }
124	      );
125	      const captureData = await captureRes.json();
126	
127	      // Tratar hold expirado (fallback charge_on_demand)
128	      const isHoldExpired =
129	        !captureRes.ok &&
130	        (captureData.errors?.[0]?.description?.toLowerCase().includes('expir') ||
131	          captureData.errors?.[0]?.code === 'invalid_action' ||
132	          captureRes.status === 400);
133	
134	      if (isHoldExpired) {
135	        console.warn(
136	          `[capture-payment] Hold expirado (job=${jobId}), executando charge_on_demand.`
137	        );
138	        return await chargeOnDemand(
139	          supabaseAdmin,
140	          jobId,
141	          app.worker_id ?? workerId,
142	          workerWalletId,
143	          job.company_id,
144	          job.budget,
145	          job.title,
146	          req,
147	          corsHeaders
148	        );
149	      }
150	
151	      if (!captureRes.ok) {
152	        throw new Error(
153	          captureData.errors?.[0]?.description ||
154	          captureData.error ||
155	          'Erro ao capturar cobrança no Asaas.'
156	        );
157	      }
158	
159	      // RPC atômica: marca released + credita worker (idempotente por (wallet_id, reference_id))
160	      const { error: rpcErr } = await supabaseAdmin.rpc('capture_escrow_postpago', {
161	        p_job_id: jobId,
162	        p_worker_wallet_id: workerWalletId,
163	      });
164	
165	      if (rpcErr) {
166	        // Erro após captura no Asaas — logar para reconciliação
167	        console.error(
168	          `[capture-payment] RPC capture_escrow_postpago falhou após captura Asaas. ` +
169	          `job=${jobId} asaas_payment_id=${asaasPaymentId}. Erro: ${rpcErr.message}`
170	        );
171	        throw new Error('Falha ao registrar crédito. Pagamento foi capturado — contacte o suporte.');
172	      }
173	
174	      return new Response(
175	        JSON.stringify({ success: true }),
176	        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
177	      );
178	    }
179	
180	    // --- Escrow já capturado/released → idempotente ---
181	    if (escrow && (escrow.status === 'released' || escrow.status === 'captured')) {
182	      return new Response(
183	        JSON.stringify({ success: true, idempotent: true }),
184	        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
185	      );
186	    }
187	
188	    // --- Caminho B: sem hold (charge_on_demand / job postpago sem pré-auth) ---
189	    if (!escrow || escrow.status === 'refunded') {
190	      return await chargeOnDemand(
191	        supabaseAdmin,
192	        jobId,
193	        workerId,
194	        workerWalletId,
195	        job.company_id,
196	        job.budget,
197	        job.title,
198	        req,
199	        corsHeaders
200	      );
201	    }
202	
203	    throw new Error(`Estado de escrow inesperado: ${escrow?.status ?? 'ausente'}.`);
204	  } catch (error: unknown) {
205	    const msg = error instanceof Error ? error.message : 'Erro interno.';
206	    console.error('asaas-capture-payment error:', msg);
207	    return new Response(
208	      JSON.stringify({ error: msg }),
209	      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 400 }
210	    );
211	  }
212	});
