214	// ---------------------------------------------------------------------------
215	// Charge-on-demand: cobrança direta com token (sem hold prévio).
216	// Usado quando: modo charge_on_demand, hold expirado, ou sem pré-auth disponível.
217	// ---------------------------------------------------------------------------
218	
219	async function chargeOnDemand(
220	  // deno-lint-ignore no-explicit-any
221	  supabaseAdmin: any,
222	  jobId: string,
223	  workerId: string,
224	  workerWalletId: string,
225	  companyUserId: string,
226	  amount: number,
227	  jobTitle: string,
228	  req: Request,
229	  corsHeaders: Record<string, string>
230	): Promise<Response> {
231	  // Buscar token default da empresa
232	  const { data: pm, error: pmErr } = await supabaseAdmin
233	    .from('payment_methods')
234	    .select('asaas_credit_card_token')
235	    .eq('company_id', companyUserId)
236	    .eq('is_default', true)
237	    .maybeSingle();
238	
239	  if (pmErr || !pm) {
240	    throw new Error('Método de pagamento da empresa não encontrado para cobrança direta.');
241	  }
242	
243	  const { data: companyWallet } = await supabaseAdmin
244	    .from('wallets')
245	    .select('asaas_customer_id')
246	    .eq('user_id', companyUserId)
247	    .maybeSingle();
248	
249	  if (!companyWallet?.asaas_customer_id) {
250	    throw new Error('Conta Asaas da empresa não encontrada.');
251	  }
252	
253	  const remoteIp =
254	    req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ||
255	    req.headers.get('x-real-ip') ||
256	    '0.0.0.0';
257	
258	  const dueDate = new Date();
259	  dueDate.setDate(dueDate.getDate() + 1);
260	
261	  // Cobrança direta (sem authorizeOnly)
262	  const chargeRes = await fetch(`${ASAAS_API_URL}/payments`, {
263	    method: 'POST',
264	    headers: getAsaasHeaders(),
265	    body: JSON.stringify({
266	      customer: companyWallet.asaas_customer_id,
267	      billingType: 'CREDIT_CARD',
268	      value: amount,
269	      dueDate: dueDate.toISOString().split('T')[0],
270	      description: `Pagamento de turno: ${jobTitle}`,
271	      externalReference: jobId,
272	      creditCardToken: pm.asaas_credit_card_token,
273	      remoteIp,
274	    }),
275	  });
276	
277	  const chargeData = await chargeRes.json();
278	  if (!chargeRes.ok) {
279	    throw new Error(
280	      chargeData.errors?.[0]?.description ||
281	      chargeData.error ||
282	      'Erro ao cobrar cartão da empresa.'
283	    );
284	  }
285	
286	  const asaasPaymentId: string = chargeData.id;
287	
288	  // Buscar carteira da empresa para authorize_escrow_postpago
289	  const { data: escrowExists } = await supabaseAdmin
290	    .from('escrow_transactions')
291	    .select('id')
292	    .eq('job_id', jobId)
293	    .eq('kind', 'postpaid')
294	    .maybeSingle();
295	
296	  // Se não há escrow (charge_on_demand original), criar e capturar no mesmo passo
297	  if (!escrowExists) {
298	    // Buscar applicationId para authorize_escrow
299	    const { data: application } = await supabaseAdmin
300	      .from('applications')
301	      .select('id')
302	      .eq('job_id', jobId)
303	      .eq('worker_id', workerId)
304	      .maybeSingle();
305	
306	    const applicationId = application?.id ?? null;
307	
308	    // 1. Authorize (grava o escrow)
309	    const { error: authRpcErr } = await supabaseAdmin.rpc('authorize_escrow_postpago', {
310	      p_job_id: jobId,
311	      p_application_id: applicationId,
312	      p_amount: amount,
313	      p_asaas_payment_id: asaasPaymentId,
314	      p_company_user_id: companyUserId,
315	    });
316	
317	    if (authRpcErr && authRpcErr.code !== '23505') {
318	      console.error(`[charge-on-demand] authorize_escrow_postpago falhou: ${authRpcErr.message}`);
319	      throw new Error('Falha ao registrar escrow após cobrança. Contacte o suporte.');
320	    }
321	  }
322	
323	  // 2. Capture (credita worker — idempotente)
324	  const { error: capRpcErr } = await supabaseAdmin.rpc('capture_escrow_postpago', {
325	    p_job_id: jobId,
326	    p_worker_wallet_id: workerWalletId,
327	  });
328	
329	  if (capRpcErr) {
330	    console.error(
331	      `[charge-on-demand] capture_escrow_postpago falhou após cobrança Asaas. ` +
332	      `job=${jobId} payment=${asaasPaymentId}. Erro: ${capRpcErr.message}`
333	    );
334	    throw new Error('Falha ao registrar crédito após cobrança. Contacte o suporte.');
335	  }
336	
337	  return new Response(
338	    JSON.stringify({ success: true, chargeOnDemand: true }),
339	    { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
340	  );
341	}
