1	/**
2	 * PaymentMethodService — gerencia métodos de pagamento on-file da empresa (cartão tokenizado).
3	 *
4	 * Slice 2 / ADR-20260622-pagamento-postpago.
5	 * PCI / Article 10: o PAN nunca toca o banco — só o token opaco do Asaas + metadados.
6	 *
7	 * Padrão de imports: relativo sem alias @/ (padrão do projeto).
8	 * Padrão de fetch: invokeFunction para operações privilegiadas; supabase direto para leituras.
9	 */
10	
11	import { supabase } from '../lib/supabase';
12	import { invokeFunction } from './api';
13	import { logError } from '../lib/logger';
14	import type { PaymentMethod } from '../types';
15	
16	// ---------------------------------------------------------------------------
17	// Tipos de input/output da UI de cartão
18	// ---------------------------------------------------------------------------
19	
20	/**
21	 * Dados necessários para tokenizar um cartão de crédito.
22	 * O PAN (number, ccv) trafega APENAS nesta chamada, server→Asaas.
23	 * NUNCA persiste no DB do Worki.
24	 */
25	export interface SaveCardInput {
26	  holderName: string;
27	  /** PAN completo — vai direto para o Asaas, não é gravado. */
28	  number: string;
29	  /** MM */
30	  expiryMonth: string;
31	  /** YYYY ou YY */
32	  expiryYear: string;
33	  /** CVV/CVC */
34	  ccv: string;
35	  holderInfo: {
36	    name: string;
37	    email: string;
38	    /** CPF ou CNPJ (só dígitos ou formatado — a Edge Function limpa). */
39	    cpfCnpj: string;
40	    /** CEP (só dígitos ou formatado). */
41	    postalCode: string;
42	    addressNumber: string;
43	    phone: string;
44	  };
45	}
46	
47	export interface SaveCardResult {
48	  success: boolean;
49	  paymentMethodId?: string;
50	  brand?: string | null;
51	  last4?: string | null;
52	  error?: string;
53	}
54	
55	export interface CapturePaymentResult {
56	  success: boolean;
57	  error?: string;
58	  chargeOnDemand?: boolean;
59	}
60	
61	export interface ReleaseHoldResult {
62	  success: boolean;
63	  error?: string;
64	}
