66	// ---------------------------------------------------------------------------
67	// Service
68	// ---------------------------------------------------------------------------
69	
70	export const PaymentMethodService = {
71	  /**
72	   * Tokeniza e salva um cartão de crédito da empresa.
73	   *
74	   * Invoca a Edge Function `asaas-tokenize-card` (Article 10: PAN não passa pelo DB).
75	   * Idempotente: re-tokenizar o mesmo cartão não cria linha duplicada (UNIQUE company+token).
76	   *
77	   * @param input Dados do cartão (PAN + holderInfo).
78	   * @returns { success, paymentMethodId, brand, last4 } ou { success: false, error }.
79	   */
80	  async savePaymentMethod(input: SaveCardInput): Promise<SaveCardResult> {
81	    try {
82	      const result = await invokeFunction<{
83	        success: boolean;
84	        paymentMethodId?: string;
85	        brand?: string | null;
86	        last4?: string | null;
87	        error?: string;
88	      }>('asaas-tokenize-card', input as unknown as Record<string, unknown>);
89	
90	      if (!result.success) {
91	        return { success: false, error: result.error || 'Erro ao salvar cartão.' };
92	      }
93	
94	      return {
95	        success: true,
96	        paymentMethodId: result.paymentMethodId,
97	        brand: result.brand,
98	        last4: result.last4,
99	      };
100	    } catch (error: unknown) {
101	      logError('paymentMethodService.savePaymentMethod', error);
102	      return {
103	        success: false,
104	        error: error instanceof Error ? error.message : 'Erro ao salvar cartão.',
105	      };
106	    }
107	  },
108	
109	  /**
110	   * Lista os métodos de pagamento cadastrados pela empresa autenticada.
111	   * Leitura direta via supabase (RLS garante isolamento por dono).
112	   */
113	  async listPaymentMethods(): Promise<PaymentMethod[]> {
114	    try {
115	      const { data: { user } } = await supabase.auth.getUser();
116	      if (!user) return [];
117	
118	      // Resolver company_id a partir do owner_id
119	      const { data: company, error: companyErr } = await supabase
120	        .from('companies')
121	        .select('id')
122	        .eq('owner_id', user.id)
123	        .maybeSingle();
124	
125	      if (companyErr || !company) return [];
126	
127	      const { data, error } = await supabase
128	        .from('payment_methods')
129	        .select('id, company_id, brand, last4, holder_name, is_default, created_at, updated_at')
130	        .eq('company_id', company.id)
131	        .order('is_default', { ascending: false })
132	        .order('created_at', { ascending: false });
133	
134	      if (error) {
135	        logError('paymentMethodService.listPaymentMethods', error);
136	        return [];
137	      }
138	
139	      // Não expor asaas_credit_card_token na listagem (PCI — token opaco, mas desnecessário na UI)
140	      return (data ?? []) as PaymentMethod[];
141	    } catch (error: unknown) {
142	      logError('paymentMethodService.listPaymentMethods', error);
143	      return [];
144	    }
145	  },
