147	  /**
148	   * Retorna o método de pagamento default da empresa autenticada, ou null.
149	   */
150	  async getDefaultPaymentMethod(): Promise<PaymentMethod | null> {
151	    try {
152	      const { data: { user } } = await supabase.auth.getUser();
153	      if (!user) return null;
154	
155	      const { data: company } = await supabase
156	        .from('companies')
