53	/** Janela de expiração do convite em horas (R8). Default = 48h. */
54	const DEFAULT_INVITE_EXPIRY_HOURS = 48;
55	
56	export interface InviteWorkerToShiftOptions {
57	  /** Horas até o convite expirar (default: 48). */
58	  expiresInHours?: number;
