79	/** Obtém o company_id da sessão autenticada (empresa). */
80	async function getAuthCompanyId(): Promise<string> {
81	  const {
82	    data: { user },
83	  } = await supabase.auth.getUser();
84	  if (!user) throw new Error('Sessão expirada. Faça login novamente.');
85	
86	  const { data: company, error } = await supabase
87	    .from('companies')
88	    .select('id')
89	    .eq('owner_id', user.id)
90	    .maybeSingle();
91	
92	  if (error) throw error;
93	  if (!company) throw new Error('Perfil de empresa não encontrado.');
94	
95	  return company.id as string;
