105	// ---------------------------------------------------------------------------
106	// ShiftInviteService
107	// ---------------------------------------------------------------------------
108	
109	export const ShiftInviteService = {
110	  // -------------------------------------------------------------------------
111	  // EMPRESA: convidar worker para turno
112	  // -------------------------------------------------------------------------
113	
114	  /**
115	   * Convida um worker da equipe para um turno específico.
116	   *
117	   * Pré-condições verificadas:
118	   *  1. O worker é conexão 'accepted' da empresa (R2 — lista fechada).
119	   *  2. Não existe convite ativo (invited) para o mesmo job+worker.
120	   *
121	   * Ações:
122	   *  1. Insere em `applications` com status='invited'.
123	   *  2. Cria notificação in-app (insert em `notifications`).
124	   *  3. Invoca `send-notification` para entrega por e-mail.
125	   *
126	   * Não chama reserve_escrow (Slice 2).
127	   *
128	   * @param jobId    UUID do turno (job).
129	   * @param workerId UUID do worker a convidar.
130	   * @param opts     Opções adicionais.
131	   */
132	  async inviteWorkerToShift(
133	    jobId: string,
134	    workerId: string,
135	    opts: InviteWorkerToShiftOptions = {},
136	  ): Promise<InviteWorkerResult> {
137	    try {
138	      const companyId = await getAuthCompanyId();
139	
140	      // 1. Validar que o worker está na equipe aceita (R2)
141	      const inTeam = await TeamConnectionService.isWorkerInTeam(companyId, workerId);
142	      if (!inTeam) {
143	        return {
144	          application: null,
145	          error:
146	            'O freela não está na sua equipe. Adicione-o primeiro para poder convidar.',
147	        };
148	      }
149	
150	      // 2. Verificar se já existe convite pendente (idempotência)
151	      const { data: existing, error: checkErr } = await supabase
152	        .from('applications')
153	        .select('id, status')
154	        .eq('job_id', jobId)
155	        .eq('worker_id', workerId)
156	        .maybeSingle();
157	
158	      if (checkErr) {
159	        logError('shiftInvite.inviteWorkerToShift.check', checkErr);
160	        return { application: null, error: 'Erro ao verificar convite existente.' };
161	      }
162	
163	      if (existing) {
164	        // Já existe application (qualquer status)
165	        if (existing.status === 'invited') {
166	          return {
167	            application: existing as Application,
168	            alreadyInvited: true,
169	          };
170	        }
171	        return {
172	          application: null,
173	          error: `Já existe uma candidatura para este turno com status '${existing.status}'.`,
174	        };
175	      }
176	
177	      // 3. Calcular expiração
178	      const expiresInHours = opts.expiresInHours ?? DEFAULT_INVITE_EXPIRY_HOURS;
179	      const expiresAt = calcExpiry(expiresInHours);
180	      const now = new Date().toISOString();
181	
182	      // 4. Inserir convite em applications
183	      const { data: application, error: insertErr } = await supabase
184	        .from('applications')
185	        .insert({
186	          job_id: jobId,
187	          worker_id: workerId,
188	          status: 'invited' as ApplicationStatus,
189	          invited_by_company_at: now,
190	          invitation_expires_at: expiresAt,
191	        })
192	        .select()
193	        .single();
194	
195	      if (insertErr) {
196	        if (insertErr.code === '23505') {
197	          return { application: null, alreadyInvited: true };
198	        }
199	        logError('shiftInvite.inviteWorkerToShift.insert', insertErr);
200	        return { application: null, error: 'Não foi possível criar o convite.' };
201	      }
202	
203	      // 5. Notificação in-app (insert direto em notifications)
204	      const { error: notifErr } = await supabase.from('notifications').insert({
205	        user_id: workerId,
206	        type: 'status_change',
207	        title: 'Novo convite de turno',
208	        message:
209	          opts.message ??
210	          'Você recebeu um convite para um turno. Acesse "Convites" para aceitar ou recusar.',
211	        link: `/my-jobs`,
212	      });
213	
214	      if (notifErr) {
215	        // Não bloqueia — a application foi criada; notificação é best-effort
216	        logError('shiftInvite.inviteWorkerToShift.notif', notifErr);
217	      }
218	
219	      // 6. Entrega por e-mail via send-notification (best-effort)
220	      try {
221	        await invokeFunction('send-notification', {
222	          userId: workerId,
223	          type: 'shift_invite',
224	          data: {
225	            jobId,
226	            applicationId: application.id,
227	            expiresAt,
228	          },
229	        });
230	      } catch (emailErr) {
231	        // Edge function falhou — não bloqueia o convite
232	        logError('shiftInvite.inviteWorkerToShift.email', emailErr);
233	      }
234	
235	      return { application: application as Application };
236	    } catch (err) {
237	      logError('shiftInvite.inviteWorkerToShift', err);
238	      return {
239	        application: null,
240	        error: err instanceof Error ? err.message : 'Erro inesperado.',
241	      };
242	    }
243	  },
244	
245	  // -------------------------------------------------------------------------
246	  // WORKER: responder ao convite (aceitar ou recusar)
247	  // -------------------------------------------------------------------------
248	
249	  /**
250	   * Worker responde a um convite de turno.
251	   *
252	   * Máquina de estados (validada aqui — ADR-001):
253	   *   'invited' → 'hired'    (quando accepted)
254	   *   'invited' → 'declined' (quando declined — NEUTRO, zero punição — R7)
255	   *
256	   * NÃO chama reserve_escrow (postpago é Slice 2; Slice 2 adiciona o hook aqui).
257	   *
258	   * @param applicationId UUID da application (convite).
259	   * @param response      'accepted' | 'declined'.
260	   */
261	  async respondToInvite(
262	    applicationId: string,
263	    response: InvitationResponse,
264	  ): Promise<RespondToInviteResult> {
265	    try {
266	      const {
267	        data: { user },
268	      } = await supabase.auth.getUser();
269	      if (!user) return { success: false, error: 'Sessão expirada.' };
270	
271	      // 1. Buscar application atual (validar máquina de estados)
272	      const { data: current, error: fetchErr } = await supabase
273	        .from('applications')
274	        .select('id, status, worker_id, job_id, invited_by_company_at, invitation_expires_at')
275	        .eq('id', applicationId)
276	        .maybeSingle();
277	
278	      if (fetchErr) {
279	        logError('shiftInvite.respondToInvite.fetch', fetchErr);
280	        return { success: false, error: 'Convite não encontrado.' };
281	      }
282	      if (!current) return { success: false, error: 'Convite não encontrado.' };
283	      if (current.worker_id !== user.id) {
284	        return { success: false, error: 'Este convite não é para você.' };
285	      }
286	      if (current.status !== 'invited') {
287	        return {
288	          success: false,
289	          error: `Transição inválida: status atual é '${current.status}', esperado 'invited'.`,
290	        };
291	      }
292	
293	      // 2. Verificar expiração (R8)
294	      if (current.invitation_expires_at) {
295	        const expiresAt = new Date(current.invitation_expires_at as string);
296	        if (expiresAt < new Date()) {
297	          return {
298	            success: false,
299	            error: 'Este convite expirou. O operador precisará reenviar um novo convite.',
300	          };
301	        }
302	      }
303	
304	      // 3. Mapear response → status final
305	      //    accepted → 'hired' (turno confirmado para os dois lados — sem escrow neste slice)
306	      //    declined → 'declined' (neutro — R7)
307	      const newStatus: ApplicationStatus = response === 'accepted' ? 'hired' : 'declined';
308	      const now = new Date().toISOString();
309	
310	      const { error: updateErr } = await supabase
311	        .from('applications')
312	        .update({
313	          status: newStatus,
314	          invitation_response: response,
315	          invitation_responded_at: now,
316	        })
317	        .eq('id', applicationId)
318	        .eq('worker_id', user.id);
319	
320	      if (updateErr) {
321	        logError('shiftInvite.respondToInvite.update', updateErr);
322	        return { success: false, error: 'Erro ao registrar resposta.' };
323	      }
324	
325	      // 4. Pré-autorização postpago (best-effort — não bloqueia o aceite em caso de falha).
326	      //    Modo 'authorize': cria hold no cartão da empresa. Modo 'charge_on_demand': no-op aqui.
327	      //    A captura (ou cobrança direta) ocorre na conclusão via asaas-capture-payment.
328	      if (response === 'accepted') {
329	        await dispatchAuthorizePayment(current.job_id, applicationId);
330	      }
331	
332	      // 5. Notificação in-app para a empresa (best-effort)
333	      if (response === 'accepted') {
334	        // Buscar company para notificar o operador
335	        const { data: job } = await supabase
336	          .from('applications')
337	          .select('job:jobs(company_id)')
338	          .eq('id', applicationId)
339	          .maybeSingle();
340	
341	        // job.job é um objeto com company_id
342	        const companyId = (job?.job as { company_id?: string } | null)?.company_id;
343	
344	        if (companyId) {
345	          // Buscar owner da empresa
346	          const { data: company } = await supabase
347	            .from('companies')
348	            .select('owner_id')
349	            .eq('id', companyId)
350	            .maybeSingle();
351	
352	          if (company?.owner_id) {
353	            const { error: notifErr } = await supabase.from('notifications').insert({
354	              user_id: company.owner_id,
355	              type: 'status_change',
356	              title: 'Freela aceitou o turno',
357	              message: 'Um freela aceitou seu convite de turno.',
358	              link: `/company/jobs/${current.job_id}/candidates`,
359	            });
360	
361	            if (notifErr) {
362	              logError('shiftInvite.respondToInvite.notif', notifErr);
363	            }
364	          }
365	        }
366	      }
367	
368	      return { success: true };
369	    } catch (err) {
370	      logError('shiftInvite.respondToInvite', err);
371	      return {
372	        success: false,
373	        error: err instanceof Error ? err.message : 'Erro inesperado.',
374	      };
375	    }
376	  },
377	
378	  // -------------------------------------------------------------------------
379	  // Listagem de convites pendentes (worker)
380	  // -------------------------------------------------------------------------
381	
382	  /**
383	   * Lista convites de turno pendentes ('invited') do worker autenticado.
384	   * Inclui dados do job e da empresa para a aba "Convites".
385	   */
386	  async listPendingInvites(): Promise<Application[]> {
387	    try {
388	      const {
389	        data: { user },
390	      } = await supabase.auth.getUser();
391	      if (!user) return [];
392	
393	      const { data, error } = await supabase
394	        .from('applications')
395	        .select(
396	          `
397	          *,
398	          job:jobs (
399	            id,
400	            title,
401	            description,
402	            briefing,
403	            location,
404	            start_date,
405	            work_start_time,
406	            work_end_time,
407	            budget,
408	            has_lunch,
409	            company_id,
410	            company:companies (
411	              id,
412	              name,
413	              logo_url,
414	              rating_average
415	            )
416	          )
417	        `,
418	        )
419	        .eq('worker_id', user.id)
420	        .eq('status', 'invited')
421	        .order('invited_by_company_at', { ascending: false });
422	
423	      if (error) {
424	        logError('shiftInvite.listPendingInvites', error);
425	        return [];
426	      }
427	
428	      return (data ?? []) as Application[];
429	    } catch (err) {
430	      logError('shiftInvite.listPendingInvites', err);
431	      return [];
432	    }
433	  },
434	
435	  /**
436	   * Lista convites enviados por uma empresa para um job específico.
437	   * Para o operador acompanhar respostas.
