16	export interface WalletTransaction {
17	    id: string;
18	    wallet_id: string;
19	    amount: number;
20	    type: 'credit' | 'debit' | 'escrow_reserve' | 'escrow_release' | 'initial_balance' | 'platform_fee' | 'escrow_authorize';
21	    description: string | null;
22	    reference_id: string | null;
23	    created_at: string;
