12	// Allowlist of origins that may call these functions. Includes the configured
13	// production origin (CORS_ORIGIN, e.g. the Vercel URL) plus local dev origins so
14	// `npm run dev` on localhost:5173 is not blocked by CORS in production.
15	const STATIC_ALLOWED_ORIGINS = [
16	    'http://localhost:5173',
17	    'http://127.0.0.1:5173',
18	    'http://localhost:3000',
19	    'https://worki-opal.vercel.app',
20	];
