22	const ALLOWED_ORIGINS = [
23	    ...(CORS_ORIGIN ? [CORS_ORIGIN] : []),
24	    ...STATIC_ALLOWED_ORIGINS,
25	];
26	
27	/**
28	 * Returns CORS headers with the Access-Control-Allow-Origin dynamically
29	 * reflected from the request's Origin header when it is in the allowlist.
30	 * Falls back to the configured ALLOWED_ORIGIN otherwise.
31	 */
32	export function getCorsHeaders(req?: Request) {
33	    const requestOrigin = req?.headers.get('Origin') ?? '';
34	    const origin = ALLOWED_ORIGINS.includes(requestOrigin)
35	        ? requestOrigin
36	        : ALLOWED_ORIGIN;
37	    return {
38	        'Access-Control-Allow-Origin': origin,
39	        'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
