1	// Simple in-memory rate limiter for edge functions
2	// Limits requests per user per function within a time window
3	
4	const requests = new Map<string, { count: number; resetAt: number }>();
5	
6	const CLEANUP_INTERVAL = 60_000; // 1 minute
7	let lastCleanup = Date.now();
8	
9	function cleanup() {
10	    const now = Date.now();
11	    if (now - lastCleanup < CLEANUP_INTERVAL) return;
12	    lastCleanup = now;
13	    for (const [key, val] of requests) {
14	        if (now > val.resetAt) requests.delete(key);
15	    }
16	}
17	
18	/**
19	 * Check if a request is rate limited.
20	 * @param userId - User identifier
21	 * @param action - Action name (e.g. 'deposit', 'withdraw')
22	 * @param maxRequests - Max requests in window (default: 10)
23	 * @param windowMs - Time window in ms (default: 60000 = 1 min)
24	 * @returns true if rate limited (should block), false if allowed
25	 */
26	export function isRateLimited(
27	    userId: string,
28	    action: string,
29	    maxRequests = 10,
30	    windowMs = 60_000
31	): boolean {
32	    cleanup();
33	    const key = `${action}:${userId}`;
34	    const now = Date.now();
35	    const entry = requests.get(key);
36	
37	    if (!entry || now > entry.resetAt) {
38	        requests.set(key, { count: 1, resetAt: now + windowMs });
39	        return false;
40	    }
41	
42	    entry.count++;
43	    if (entry.count > maxRequests) {
44	        return true;
45	    }
46	
47	    return false;
48	}
